# Wine Pairing API
import requests

WINE_API_KEY = "85eeebefe6edf1ebdac6e916e1a614ac7444ea76"
BASE_URL = "https://api.spoonacular.com/food/wine"

def get_wine_pairing(food, max_price=None):
    """Get wine pairing suggestions"""
    params = {
        "apiKey": WINE_API_KEY,
        "food": food
    }
    if max_price:
        params["maxPrice"] = max_price

    response = requests.get(f"{BASE_URL}/pairing", params=params)
    return response.json()

def get_wine_description(wine_name):
    """Get description of a wine"""
    params = {
        "apiKey": WINE_API_KEY,
        "wine": wine_name
    }
    response = requests.get(f"{BASE_URL}/description", params=params)
    return response.json()
